import{_ as e,c as t,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"题要","description":"周易集注 - 题要","frontmatter":{"title":"题要","description":"周易集注 - 题要"},"headers":[],"relativePath":"zh/classics/jizhu/002.md","filePath":"zh/classics/jizhu/002.md"}'),r={name:"zh/classics/jizhu/002.md"};function i(c,a,_,o,n,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="题要" tabindex="-1">题要 <a class="header-anchor" href="#题要" aria-label="Permalink to “题要”">​</a></h1><p>臣等谨案，《周易集注》十六卷，明来知德撰。知德，字矣鲜，梁山人，嘉靖壬子举人。万历三十年，总督王象乾巡抚郭子章荐授翰林院待诏，知德以老疾辞诏，以所授官至任，事迹具《明史儒林传》。</p><p>知德自乡举之后，即移居万县深山中，精思易理。自隆庆庚午至万历戊戌，阅二十九年而成此书。其立说专取《系辞》中错综其数以论易象，而以杂卦治之。</p><p>错者，阴阳对错，如先天圆图：干错坤，坎错离，八卦相错是也。综者，一上一下，如屯蒙之类，本是一卦，在下为屯，在上为蒙。载之文王序卦是也。</p><p>其论错有四正错，有四隅错。论综有四正综。有四隅综;有以正综隅，有以隅综正。其论象有卦情之象，有卦画之象，有大象之象，有中爻之象，有错卦之象，有综卦之象，有爻变之象，有占中之象。其注皆先释象义、字义，及错综义，然后训本卦本爻正义，皆由冥心力索，得其端倪，因而参互旁通，自成一说，当时推为绝学。</p><p>然上下经各十八卦，本税与权之旧说。而所说中爻之象，亦即汉以来互体之法。特知德纵横推阐，专明斯义，较先儒为详尽耳。其自序乃高自位置，至谓孔子没后而易亡，二千年有如长夜，岂非伏处村塾，不尽睹遗文秘籍之传，不尽闻老师宿儒之论。师心自悟，偶有所得，遽夜郎自大哉。故百馀年来信其说者颇多，攻其说者亦不少。然易道渊深，包罗众象。随得一隙而入，皆能宛转关通，有所阐发，亦不必尽以支离繁碎斥也。</p><p>乾隆四十六年九月恭校上</p><p>总纂官　臣 纪昀　臣 陆锡熊　臣 孙士毅</p><p>总校官　臣 陆费墀</p>',9)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
